using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 bool AtCommunityCamp=>Community.Established&&dungeon==null&&ExpeditionGame.Distance(player.Position.X,player.Position.Z,Community.X,Community.Z)<20;
 void CommunityAction(string data){if(CoopClient||dungeon!=null||data.Length>200)return;var bits=data.Split('|');if(bits.Length!=2)return;var n=Community.Survivors.FirstOrDefault(n=>n.Id==bits[0]);string operation=bits[1];int priorSupplies=Community.Food+Community.Water+Community.Ammo+Community.Stock[2];bool near=n!=null&&Distance(player.Position,NpcPoint(n))<4;
  if(operation.StartsWith("talk-")||operation=="vigil"){CommunitySocialAction(n,operation,near);return;}
  if(operation=="rescue"){if(n==null||n.State!="trapped"||!near)return;if(RescueGuardIds(n).Any(id=>!game.Skills.Defeated.Contains(id))){game.Notice="Clear the infected surrounding this survivor first";return;}game.Change(()=>{n.State="rescued";n.EscortOwner=CommunityOwner;game.Career.Gain(80);game.AwardResearch("rescue/"+n.Id,5);});game.Notice=n.Name+" will follow you / bring them to a sheltered cot";}
  else if(operation=="escort"){if(n==null||n.State!="rescued"||!near)return;game.Change(()=>n.EscortOwner=CommunityOwner);game.Notice=n.Name+" will follow you back to camp";}else if(operation=="recruit"){if(n==null)return;string reason=Community.RecruitReason(n,game,player.Position.X,player.Position.Z);if(reason!="Ready"){game.Notice=reason;return;}game.Change(()=>Community.Recruit(n,game,player.Position.X,player.Position.Z));game.Notice=n.Name+" joined your camp / F7 opens community management";}
  else if(operation=="bed"){if(n==null||!n.Member||!AtCommunityCamp)return;var bed=Community.FreeBed(game.Building.Pieces,player.Position.X,player.Position.Z);if(bed==null){game.Notice="No free sheltered cot nearby";return;}game.Change(()=>n.BedId=bed.Id);game.Notice="Resident assigned to the new sheltered cot";}else if(operation=="aid"){if(n==null||!near||n.State is "trapped" or "dead"||game.Life.Bandages<1){game.Notice="Stand beside a rescued survivor with a bandage";return;}game.Change(()=>{game.Life.Bandages--;n.Downed=false;n.Health=Math.Max(10,n.Health);n.Treatment=60;n.DownTime=0;});game.Notice="First aid applied / recovery over the next minute";}
  else if(operation is "wood" or "supplies" or "guard" or "follow" or "stay"){if(n==null||!n.Member||!AtCommunityCamp&&!near)return;if(operation=="follow"&&Standing(n.Id).Value<0){game.Notice="They do not trust you enough to follow";return;}if(operation=="follow"&&(n.Downed||n.Injury>=70)){game.Notice="This survivor needs to recover at camp";return;}if(operation=="follow"&&Community.Survivors.Any(s=>s.Member&&s.Id!=n.Id&&!string.IsNullOrEmpty(s.Owner))){game.Notice="Only one active companion per community";return;}if(!string.IsNullOrEmpty(n.Owner)&&n.Owner!=CommunityOwner){game.Notice="That survivor is accompanying another player";return;}game.Change(()=>{if(operation=="follow")n.Owner=CommunityOwner;else{n.Owner="";if(operation!="stay")n.Job=operation;}n.Work=0;});game.Notice=operation=="follow"?n.Name+" is following you":n.Name+" / "+n.Job+" at camp";}
  else if(operation.StartsWith("deposit-")||operation=="take-wood"){if(!AtCommunityCamp){game.Notice="Return within 20m of camp to transfer supplies";return;}game.Change(()=>{switch(operation){case "deposit-food":int food=Math.Min(3,Math.Min(game.Life.Food,100-Community.Food));game.Life.Food-=food;Community.Food+=food;break;case "deposit-water":int water=Math.Min(3,Math.Min(game.Craft.Water,100-Community.Water));game.Craft.Water-=water;Community.Water+=water;break;case "deposit-fiber":int fiber=Math.Min(3,Math.Min(game.Craft.Materials[2],200-Community.Stock[2]));game.Craft.Materials[2]-=fiber;Community.Stock[2]+=fiber;break;case "deposit-ammo":int ammo=Math.Min(12,Math.Min(game.Craft.Reserve,200-Community.Ammo));game.Craft.Reserve-=ammo;Community.Ammo+=ammo;break;case "take-wood":int timber=Math.Min(5,Community.Stock[0]);Community.Stock[0]-=timber;game.Craft.Materials[0]+=timber;break;}});game.Notice="Camp supply transfer complete";}
  else return;
  if(n!=null&&operation is "rescue" or "recruit" or "aid")game.World.Changes.Remember(CommunityOwner,n.Id,operation=="rescue"?15:8,"You helped me when I needed it. / "+operation);
  if(operation.StartsWith("deposit-")&&Community.Food+Community.Water+Community.Ammo+Community.Stock[2]>priorSupplies){game.World.Changes.Remember(CommunityOwner,"home",2,"You brought supplies home.");}if(operation.StartsWith("deposit-")&&Community.Food+Community.Water+Community.Ammo+Community.Stock[2]>priorSupplies)foreach(var member in Community.Survivors.Where(s=>s.Member))game.World.Changes.Remember(CommunityOwner,member.Id,1,"You brought supplies home.");
  game.Persist();
  if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));
 }
 void OpenCommunityNpc(string id){var n=Community.Survivors.FirstOrDefault(n=>n.Id==id);if(n==null||Distance(player.Position,NpcPoint(n))>4)return;if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopCommunityPanel),id);else ShowCommunity(id);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopCommunityPanel(string id){if(CoopClient)ShowCommunity(id);}
}
